    @Test
    public void testCreateInstanceCallsKryoNewInstance() throws Exception {
        // Create a concrete class type that is not abstract or interface
        Class<String> concreteClass = String.class;

        // Create Kryo instance with proper configuration
        Kryo kryo = new Kryo();
        kryo.setInstantiatorStrategy(new DefaultInstantiatorStrategy(new StdInstantiatorStrategy()));

        // Create KryoSerializer with mocked dependencies
        TypeSerializer<String> mockTypeSerializer = mock(TypeSerializer.class);
        ArrayList<Class<?>> registeredClasses = new ArrayList<>();
        registeredClasses.add(String.class);

        // Create the actual KryoSerializer instance
        KryoSerializer<String> serializer = new KryoSerializer<>(
            concreteClass,
            new ArrayList<>(registeredClasses),
            new ArrayList<>(),
            new ArrayList<>(),
            new ArrayList<>()
        );

        // Use reflection to set the kryo field since it's private
        java.lang.reflect.Field kryoField = KryoSerializer.class.getDeclaredField("kryo");
        kryoField.setAccessible(true);
        kryoField.set(serializer, kryo);

        // Set the type field
        java.lang.reflect.Field typeField = KryoSerializer.class.getDeclaredField("type");
        typeField.setAccessible(true);
        typeField.set(serializer, concreteClass);

        // Invoke the entry point method - this should trigger kryo.newInstance()
        serializer.createInstance();
    }
}

