import org.snakeyaml.engine.v2.representer.BaseRepresenter;
import org.snakeyaml.engine.v2.representer.StandardRepresenter;

import java.io.StringWriter;
import java.util.Arrays;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

class YamlParserUtilsconvertAndDumpYamlFromFlatMap_DumpSettingsgetBestLineBreakFikaTest {

    @Test
    void testConvertAndDumpYamlFromFlatMap() {
        Map<String, Object> flattenMap = new LinkedHashMap<>();
        flattenMap.put("key1", "value1");
        flattenMap.put("parent.child.key2", "value2");
        flattenMap.put("a.b.c.d", "nestedValue");

        DumpSettings dumpSettings = new DumpSettingsBuilder().build();
        BaseRepresenter representer = new StandardRepresenter(dumpSettings);
        StreamDataWriter writer = new StreamDataWriter() {
            private final StringWriter stringWriter = new StringWriter();

            @Override
            public void write(String str) {
                stringWriter.write(str);
            }

            @Override
            public void write(String str, int off, int len) {
                stringWriter.write(str, off, len);
            }

            @Override
            public void flush() {
                // No-op for StringWriter
            }

            @Override
            public String toString() {
                return stringWriter.toString();
            }
        };
        Emitter emitter = new Emitter(dumpSettings, writer);

        YamlParserUtils.BlockerDumper blockerDumper = new YamlParserUtils.BlockerDumper(
            representer, emitter, dumpSettings
        );

        YamlParserUtils.setBlockerDumper(blockerDumper);
        YamlParserUtils.setBlockerDumperSettings(dumpSettings);

        YamlParserUtils.convertAndDumpYamlFromFlatMap(flattenMap);
    }
}

