import java.io.ByteArrayOutputStream;
import java.util.ArrayList;

import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class KryoSerializercopy_KryowriteObjectFikaTest {

    @Test
    public void testCopyTriggersKryoWriteObject() throws Exception {
        Kryo kryo = new Kryo();

        KryoSerializer<ArrayList> serializer = new KryoSerializer<>(
            ArrayList.class,
            new org.apache.flink.api.java.ExecutionEnvironment().getConfig()
        );

        ArrayList<String> list = new ArrayList<>();
        list.add("test");

        try {
            serializer.copy(list);
        } catch (Exception e) {
            // Expected - we need to trigger the KryoException path
        }

        KryoSerializer<UncopyableObject> serializer2 = new KryoSerializer<>(
            UncopyableObject.class,
            new org.apache.flink.api.java.ExecutionEnvironment().getConfig()
        );

        UncopyableObject obj = new UncopyableObject();
        serializer2.copy(obj);
    }

    private static class UncopyableObject {
        @Override
        public String toString() {
            throw new KryoException("Simulating Kryo copy failure");
        }
    }
}

