    public void testDeserializePath() throws Exception {
        // Create a mock DataInputView that provides minimal data
        DataInputView mockInputView = new DataInputView() {
            private ByteArrayInputStream bais = new ByteArrayInputStream(new byte[100]);

            @Override
            public void readFully(byte[] b) throws IOException {
                bais.read(b);
            }

            @Override
            public void readFully(byte[] b, int off, int len) throws IOException {
                bais.read(b, off, len);
            }

            @Override
            public int skipBytes(int n) throws IOException {
                return (int) bais.skip(n);
            }

            @Override
            public boolean readBoolean() throws IOException {
                return bais.read() != 0;
            }

            @Override
            public byte readByte() throws IOException {
                return (byte) bais.read();
            }

            @Override
            public int readUnsignedByte() throws IOException {
                return bais.read();
            }

            @Override
            public short readShort() throws IOException {
                return (short) ((bais.read() << 8) | bais.read());
            }

            @Override
            public int readUnsignedShort() throws IOException {
                return ((bais.read() << 8) | bais.read()) & 0xFFFF;
            }

            @Override
            public char readChar() throws IOException {
                return (char) ((bais.read() << 8) | bais.read());
            }

            @Override
            public int readInt() throws IOException {
                return (bais.read() << 24) | (bais.read() << 16) | (bais.read() << 8) | bais.read();
            }

            @Override
            public long readLong() throws IOException {
                return ((long) bais.read() << 56) |
                       ((long) bais.read() << 48) |
                       ((long) bais.read() << 40) |
                       ((long) bais.read() << 32) |
                       ((long) bais.read() << 24) |
                       ((long) bais.read() << 16) |
                       ((long) bais.read() << 8) |
                       bais.read();
            }

            @Override
            public float readFloat() throws IOException {
                return Float.intBitsToFloat(readInt());
            }

            @Override
            public double readDouble() throws IOException {
                return Double.longBitsToDouble(readLong());
            }

            @Override
            public String readLine() throws IOException {
                throw new UnsupportedOperationException();
            }

            @Override
            public String readUTF() throws IOException {
                throw new UnsupportedOperationException();
            }
        };

        // Create KryoSerializer with mocked dependencies
        Class<?> typeClass = String.class;
        KryoSerializer<?> serializer = new KryoSerializer<>(typeClass, mock(org.apache.flink.api.common.ExecutionConfig.class));

        // Use reflection to disable CONCURRENT_ACCESS_CHECK to avoid thread issues
        Field concurrentAccessCheckField = KryoSerializer.class.getDeclaredField("CONCURRENT_ACCESS_CHECK");
        concurrentAccessCheckField.setAccessible(true);
        concurrentAccessCheckField.set(null, false);

        // Initialize kryo field to ensure it's not null
        Field kryoField = KryoSerializer.class.getDeclaredField("kryo");
        kryoField.setAccessible(true);
