package org.apache.flink.util;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import java.io.File;
import java.io.FileOutputStream;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.zip.ZipEntry;
import java.util.zip.ZipOutputStream;

public class CompressionUtilsextractZipFileWithPermissions_ZipArchiveEntryisUnixSymlinkFikaTest {

    @TempDir
    private Path tempDir;

    @Test
    public void testExtractZipFileWithPermissionsInvokesIsUnixSymlink() throws IOException {
        // Create a zip file containing a symlink entry
        Path zipFilePath = tempDir.resolve("test.zip");
        Path extractDir = tempDir.resolve("extract");
        Files.createDirectories(extractDir);

        try (ZipOutputStream zos = new ZipOutputStream(new FileOutputStream(zipFilePath.toFile()))) {
            // Create a symlink entry - ZipEntry doesn't support symlinks directly,
            // but we need to create a zip that will trigger isUnixSymlink() call
            ZipEntry symlinkEntry = new ZipEntry("symlink.txt");
            // Set external attributes to indicate a symlink (Unix mode 0xA000 for symlinks)
            symlinkEntry.setExternalAttributes((0xA000L) << 16);
            zos.putNextEntry(symlinkEntry);
            zos.write("target.txt".getBytes());
            zos.closeEntry();

            // Add a regular file to avoid empty zip issues
            ZipEntry regularEntry = new ZipEntry("regular.txt");
            zos.putNextEntry(regularEntry);
            zos.write("content".getBytes());
            zos.closeEntry();
        }

        // Execute the entry point method
        CompressionUtils.extractZipFileWithPermissions(zipFilePath.toString(), extractDir.toString());
    }
}

