        when(markedException.getProblem()).thenReturn("found duplicate key key1");
        when(markedException.getCause()).thenReturn(null);
        when(markedException.getStackTrace()).thenReturn(new StackTraceElement[0]);

        // Create a mock loader that will throw the MarkedYamlEngineException
        YamlParserUtils.LoaderHolder loaderHolder = new YamlParserUtils.LoaderHolder();
