        when(loader.loadFromString("invalid yaml")).thenThrow(markedException);

        // Use reflection to set the loader field since it's private
        java.lang.reflect.Field loaderField = YamlParserUtils.LoaderHolder.class.getDeclaredField("loader");
        loaderField.setAccessible(true);
        loaderField.set(loaderHolder, loader);

        // Try to convert invalid YAML - this should trigger the wrapExceptionToHiddenSensitiveData method
        // which will create a new YamlEngineException
        try {
            YamlParserUtils.convertToObject("invalid yaml", Object.class);
        } catch (YamlEngineException e) {
            // Expected - the YamlEngineException constructor was invoked
        }
    }

    // Helper Mark class since it's not publicly accessible
    private static class Mark {
        private final String name;
