        private final int column;
        private final int index;
        private final char[] buffer;
        private final int pointer;

        Mark(String name, int line, int column, int index, char[] buffer, int pointer) {
            this.name = name;
            this.line = line;
            this.column = column;
            this.index = index;
            this.buffer = buffer;
            this.pointer = pointer;
        }

        public String getName() {
