        // and passed to wrapExceptionToHiddenSensitiveData
        MarkedYamlEngineException markedException = new MarkedYamlEngineException(
            "Test problem",
            Optional.empty(),
            "Test context",
            Optional.empty(),
            new RuntimeException("Test cause")
