package org.apache.flink.api.java.typeutils.runtime;

import com.esotericsoftware.kryo.io.Input;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import java.io.ByteArrayInputStream;
import java.io.InputStream;

class NoFetchingInputrequire_KryoBufferUnderflowExceptionmethodFikaTest {

    @Test
    void testReadTriggersKryoBufferUnderflowException() throws Exception {
        // Create an InputStream that will return -1 (EOF) on read
        InputStream emptyStream = new ByteArrayInputStream(new byte[0]);

        // Create a NoFetchingInput with buffer size 8
        NoFetchingInput input = new NoFetchingInput(emptyStream, 8);

        // Position the buffer at the end to trigger underflow
        // First fill the buffer completely
        byte[] tempBuffer = new byte[8];
        emptyStream.read(tempBuffer); // This will read 0 bytes since stream is empty

        // Now try to read from NoFetchingInput - this should trigger require(1)
        // which will try to fill buffer and eventually throw KryoBufferUnderflowException
        try {
            input.read();
        } catch (com.esotericsoftware.kryo.KryoException e) {
            // Expected - the KryoBufferUnderflowException is wrapped in KryoException
        }
    }

    // Helper class to make NoFetchingInput accessible
    private static class NoFetchingInput extends Input {
        public NoFetchingInput(InputStream inputStream, int bufferSize) {
            super(inputStream, bufferSize);
        }
    }
}

