package org.apache.flink.api.java.typeutils.runtime.kryo;

import org.apache.flink.api.common.serialization.SerializerConfig;
import org.apache.flink.api.common.serialization.SerializerConfigImpl;
import org.junit.jupiter.api.Test;
import org.mockito.MockedStatic;
import org.mockito.Mockito;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class KryoSerializerconfigureKryoLogging_LogsetLoggerFikaTest {

    @Test
    public void testConfigureKryoLoggingTriggersLogsetLogger() {
        try (MockedStatic<LoggerFactory> loggerFactoryMock = Mockito.mockStatic(LoggerFactory.class)) {
            Logger mockLogger = mock(Logger.class);
            loggerFactoryMock.when(() -> LoggerFactory.getLogger(KryoSerializer.class))
                    .thenReturn(mockLogger);

            when(mockLogger.isTraceEnabled()).thenReturn(true);

            SerializerConfig serializerConfig = mock(SerializerConfigImpl.class);
            when(serializerConfig.getDefaultKryoSerializerClasses()).thenReturn(null);
            when(serializerConfig.getRegisteredKryoTypes()).thenReturn(null);
            when(serializerConfig.getRegisteredTypesWithKryoSerializerClasses()).thenReturn(null);
            when(serializerConfig.isForceKryoAvroEnabled()).thenReturn(false);

            new KryoSerializer<>(String.class, serializerConfig);
        }
    }
}

