public class PojoTypeInfo_KryoSerializerconfigureKryoLogging_LogTRACEFikaTest {

    @Test
    public void testCreateSerializerTriggersKryoLogging() throws Exception {
        // Create a PojoTypeInfo instance
        PojoTypeInfo<TestPojo> typeInfo = new PojoTypeInfo<>(
            TestPojo.class,
            new org.apache.flink.api.common.typeinfo.TypeInformation[0],
            new org.apache.flink.api.common.typeutils.TypeSerializer[0],
            new String[0]
        );

        // Create SerializerConfig with forceKryo enabled to trigger KryoSerializer instantiation
        SerializerConfig config = new SerializerConfig();

        // Use reflection to set forceKryo flag since it might not have a public setter
        Field forceKryoField = SerializerConfig.class.getDeclaredField("forceKryo");
        forceKryoField.setAccessible(true);
        forceKryoField.set(config, true);

        // This should trigger the static initializer of KryoSerializer
        // which calls configureKryoLogging() -> Log.TRACE()
        typeInfo.createSerializer(config);

        // Reset static state to ensure test can run multiple times
        // Clear any cached KryoSerializer instances if they exist
        clearKryoSerializerStaticState();
    }

    private void clearKryoSerializerStaticState() throws Exception {
        // Reset the static logging configuration in KryoSerializer
        // by triggering configureKryoLogging again with different conditions
        // This is done via reflection to avoid affecting other tests
        try {
            Field loggerField = KryoSerializer.class.getDeclaredField("LOG");
            loggerField.setAccessible(true);
            Object logger = loggerField.get(null);

            // Use reflection to check if trace is enabled
            Class<?> loggerClass = logger.getClass();
            java.lang.reflect.Method isTraceEnabledMethod = loggerClass.getMethod("isTraceEnabled");
            Boolean isTraceEnabled = (Boolean) isTraceEnabledMethod.invoke(logger);

            // If trace was enabled, we need to reset the Log logger
            if (isTraceEnabled) {
                // Reset com.esotericsoftware.minlog.Log logger to null
                Class<?> minlogLogClass = Class.forName("com.esotericsoftware.minlog.Log");
                Field loggerFieldMinlog = minlogLogClass.getDeclaredField("logger");
                loggerFieldMinlog.setAccessible(true);
                loggerFieldMinlog.set(null, null);
            }
        } catch (Exception e) {
            // Ignore cleanup errors
        }
    }

    // Simple test POJO class
    public static class TestPojo {
        private String field;

        public String getField() {
            return field;
        }

        public void setField(String field) {
            this.field = field;
        }
    }
}

