package org.apache.flink.util;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import java.io.File;
import java.io.FileOutputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import org.apache.commons.compress.archivers.tar.TarArchiveEntry;
import org.apache.commons.compress.archivers.tar.TarArchiveOutputStream;
import org.apache.commons.compress.compressors.gzip.GzipCompressorOutputStream;

public class CompressionUtilsunpackEntry_TarArchiveEntrygetLinkNameFikaTest {

    @TempDir
    private Path tempDir;

    @Test
    public void testExtractTarFileInvokesGetLinkName() throws Exception {
        // Create a tar file with a symbolic link entry
        Path tarFile = tempDir.resolve("test.tar");

        try (FileOutputStream fos = new FileOutputStream(tarFile.toFile());
             TarArchiveOutputStream taos = new TarArchiveOutputStream(fos)) {

            // Create a regular file entry
            TarArchiveEntry fileEntry = new TarArchiveEntry("regular.txt");
            fileEntry.setSize(5);
            taos.putArchiveEntry(fileEntry);
            taos.write("hello".getBytes());
            taos.closeArchiveEntry();

            // Create a symbolic link entry - this will cause getLinkName() to be called
            TarArchiveEntry symlinkEntry = new TarArchiveEntry("link.txt", TarArchiveEntry.LF_SYMLINK);
            symlinkEntry.setLinkName("regular.txt");
            taos.putArchiveEntry(symlinkEntry);
            taos.closeArchiveEntry();
        }

        // Extract the tar file
        String sourcePath = tarFile.toAbsolutePath().toString();
        String targetPath = tempDir.resolve("extracted").toString();

        CompressionUtils.extractTarFile(sourcePath, targetPath);
    }
}

