package org.apache.flink.util;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;

public class CompressionUtilsunpackEntry_TarArchiveEntryisSymbolicLinkFikaTest {

    @TempDir
    private Path tempDir;

    @Test
    public void testExtractTarFile() throws IOException {
        // Create a minimal tar file with a symbolic link entry
        Path tarFile = tempDir.resolve("test.tar");
        Path targetDir = tempDir.resolve("target");

        // Create a simple tar file using Apache Commons Compress
        try (org.apache.commons.compress.archivers.tar.TarArchiveOutputStream taos = 
                new org.apache.commons.compress.archivers.tar.TarArchiveOutputStream(
                    Files.newOutputStream(tarFile))) {

            // Create a regular file entry
            Path regularFile = tempDir.resolve("regular.txt");
            Files.writeString(regularFile, "test content");

            org.apache.commons.compress.archivers.tar.TarArchiveEntry fileEntry = 
                new org.apache.commons.compress.archivers.tar.TarArchiveEntry(
                    regularFile.toFile(), "regular.txt");
            taos.putArchiveEntry(fileEntry);
            taos.write(Files.readAllBytes(regularFile));
            taos.closeArchiveEntry();

            // Create a symbolic link entry - this will trigger isSymbolicLink() call
            org.apache.commons.compress.archivers.tar.TarArchiveEntry symlinkEntry = 
                new org.apache.commons.compress.archivers.tar.TarArchiveEntry(
                    "link.txt", org.apache.commons.compress.archivers.tar.TarArchiveEntry.LF_SYMLINK);
            symlinkEntry.setLinkName("regular.txt");
            taos.putArchiveEntry(symlinkEntry);
            taos.closeArchiveEntry();
        }

        // Execute the entry point method
        CompressionUtils.extractTarFile(tarFile.toString(), targetDir.toString());
    }
}

