    public void testCreateSerializerTriggersMinlogLoggerInitialization() throws Exception {
        // Create a real PojoTypeInfo instance with a simple type
        PojoTypeInfo<String> typeInfo = new PojoTypeInfo<>(
            String.class,
            new java.util.ArrayList<>(),
            new java.util.ArrayList<>(),
            new java.util.ArrayList<>(),
            new java.util.ArrayList<>()
        );

        // Create a real SerializerConfig with forceKryo enabled
