        try (MockedStatic<LoggerFactory> mockedLoggerFactory = Mockito.mockStatic(LoggerFactory.class)) {
            org.slf4j.Logger mockLogger = mock(org.slf4j.Logger.class);
            Mockito.when(mockLogger.isTraceEnabled()).thenReturn(true);
            mockedLoggerFactory.when(() -> LoggerFactory.getLogger(KryoSerializer.class))
                .thenReturn(mockLogger);

            // This will trigger the static initializer of KryoSerializer
            // which will call configureKryoLogging() -> new MinlogForwarder() -> new Log.Logger()
            typeInfo.createSerializer(config);
        }
    }
}

