        // and checks LOG.isTraceEnabled(). We need to ensure trace is enabled
        // before the static initializer runs, but it already ran when class was loaded.

        // Solution: Create a new instance in a separate classloader where
        // we can set trace logging before class initialization
        ClassLoader originalClassLoader = Thread.currentThread().getContextClassLoader();

        try {
            // Create a custom classloader that will load the class fresh
            ClassLoader customLoader = new ClassLoader(originalClassLoader) {
                @Override
                public Class<?> loadClass(String name) throws ClassNotFoundException {
                    // For KryoSerializer, load it fresh
                    if (name.equals(KryoSerializer.class.getName())) {
                        return findClass(name);
                    }
                    return super.loadClass(name);
                }

                @Override
                protected Class<?> findClass(String name) throws ClassNotFoundException {
                    if (name.equals(KryoSerializer.class.getName())) {
                        // Get the class bytes from the original classloader
                        try (var inputStream = originalClassLoader.getResourceAsStream(
                                "org/apache/flink/api/java/typeutils/runtime/kryo/KryoSerializer.class")) {
                            if (inputStream == null) {
                                throw new ClassNotFoundException(name);
                            }
                            byte[] bytes = inputStream.readAllBytes();
                            return defineClass(name, bytes, 0, bytes.length);
                        } catch (Exception e) {
                            throw new ClassNotFoundException(name, e);
                        }
                    }
                    throw new ClassNotFoundException(name);
                }
            };

            // Set context classloader to our custom loader
            Thread.currentThread().setContextClassLoader(customLoader);

            // Load a fresh version of the class
            Class<?> freshKryoSerializerClass = customLoader.loadClass(
                "org.apache.flink.api.java.typeutils.runtime.kryo.KryoSerializer"
            );

            // Before instantiating, we need to ensure trace is enabled
            // We'll use reflection to get the LOG field and set trace level
