import org.apache.flink.api.common.typeutils.TypeSerializerSchemaCompatibility;
import org.apache.flink.api.common.typeutils.TypeSerializerSnapshot;
import org.apache.flink.util.LinkedOptionalMap;
import com.esotericsoftware.kryo.Serializer;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import java.io.Serializable;
import java.util.LinkedHashMap;

public class KryoSerializerSnapshot_KryoSerializerconfigureKryoLogging_LogTRACEFikaTest2 {

    @Test
    public void testResolveSchemaCompatibilityTriggersKryoLogging() throws Exception {
        // Create a snapshot with trace logging enabled
        KryoSerializerSnapshot<String> snapshot = new KryoSerializerSnapshot<>();

        // Use reflection to set snapshotData since it's private
        java.lang.reflect.Field snapshotDataField = 
            KryoSerializerSnapshot.class.getDeclaredField("snapshotData");
        snapshotDataField.setAccessible(true);

        // Create snapshot data with same type class
        KryoSerializerSnapshot.KryoSerializerSnapshotData<String> data = 
            new KryoSerializerSnapshot.KryoSerializerSnapshotData<>(
                String.class,
                new LinkedOptionalMap<>(),
                new LinkedOptionalMap<>(),
                new LinkedOptionalMap<>());
        snapshotDataField.set(snapshot, data);

        // Create old snapshot with same type class
        KryoSerializerSnapshot<String> oldSnapshot = new KryoSerializerSnapshot<>();
        KryoSerializerSnapshot.KryoSerializerSnapshotData<String> oldData = 
            new KryoSerializerSnapshot.KryoSerializerSnapshotData<>(
                String.class,
                new LinkedOptionalMap<>(),
                new LinkedOptionalMap<>(),
                new LinkedOptionalMap<>());
        snapshotDataField.set(oldSnapshot, oldData);

        // Enable TRACE logging for KryoSerializer's static logger
        // This is done by setting the root logger to TRACE level
        ch.qos.logback.classic.Logger rootLogger = 
            (ch.qos.logback.classic.Logger) org.slf4j.LoggerFactory.getLogger(
                org.slf4j.Logger.ROOT_LOGGER_NAME);
        ch.qos.logback.classic.Level originalLevel = rootLogger.getLevel();
        rootLogger.setLevel(ch.qos.logback.classic.Level.TRACE);

        try {
            // This should trigger the static initializer of KryoSerializer
            // which calls configureKryoLogging() -> Log.TRACE()
            snapshot.resolveSchemaCompatibility(oldSnapshot);
        } finally {
            // Restore original log level
            rootLogger.setLevel(originalLevel);
        }
    }
}

