            KryoSerializerSnapshot.KryoSerializerSnapshotData.class.getDeclaredField("defaultKryoSerializers");
        defaultKryoSerializersField.setAccessible(true);
        defaultKryoSerializersField.set(snapshotData, new LinkedOptionalMap<>());

        java.lang.reflect.Field defaultKryoSerializerClassesField = 
            KryoSerializerSnapshot.KryoSerializerSnapshotData.class.getDeclaredField("defaultKryoSerializerClasses");
        defaultKryoSerializerClassesField.setAccessible(true);
