@Override
public TypeSerializerSchemaCompatibility<T> resolveSchemaCompatibility(TypeSerializerSnapshot<T> oldSerializerSnapshot) {
    if (!(oldSerializerSnapshot instanceof KryoSerializerSnapshot)) {
        return TypeSerializerSchemaCompatibility.incompatible();
    }
    KryoSerializerSnapshot<T> oldKryoSerializerSnapshot = ((KryoSerializerSnapshot<T>) (oldSerializerSnapshot));
    if (snapshotData.getTypeClass() != oldKryoSerializerSnapshot.snapshotData.getTypeClass()) {
        return TypeSerializerSchemaCompatibility.incompatible();
    }
    // PATH: Test should invoke the next KryoSerializerSnapshot.resolveSchemaCompatibility(...) [step in execution path]
    return resolveSchemaCompatibility(oldKryoSerializerSnapshot);
}

private TypeSerializerSchemaCompatibility<T> resolveSchemaCompatibility(KryoSerializerSnapshot<T> oldKryoSerializerSnapshot) {
    // merge the default serializers
    final MergeResult<Class<?>, SerializableSerializer<?>> reconfiguredDefaultKryoSerializers = mergeRightIntoLeft(oldKryoSerializerSnapshot.snapshotData.getDefaultKryoSerializers(), snapshotData.getDefaultKryoSerializers());
    if (reconfiguredDefaultKryoSerializers.hasMissingKeys()) {
        logMissingKeys(reconfiguredDefaultKryoSerializers);
        return TypeSerializerSchemaCompatibility.incompatible();
    }
    // merge default serializer classes
    final MergeResult<Class<?>, Class<? extends Serializer<?>>> reconfiguredDefaultKryoSerializerClasses = mergeRightIntoLeft(oldKryoSerializerSnapshot.snapshotData.getDefaultKryoSerializerClasses(), snapshotData.getDefaultKryoSerializerClasses());
    if (reconfiguredDefaultKryoSerializerClasses.hasMissingKeys()) {
        logMissingKeys(reconfiguredDefaultKryoSerializerClasses);
        return TypeSerializerSchemaCompatibility.incompatible();
    }
    // merge registration
    final MergeResult<String, KryoRegistration> reconfiguredRegistrations = mergeRightIntoLeft(oldKryoSerializerSnapshot.snapshotData.getKryoRegistrations(), snapshotData.getKryoRegistrations());
    if (reconfiguredRegistrations.hasMissingKeys()) {
        logMissingKeys(reconfiguredRegistrations);
        return TypeSerializerSchemaCompatibility.incompatible();
    }
    // there are no missing keys, now we have to decide whether we are compatible as-is or we
    // require reconfiguration.
    // PATH: Test should invoke the next KryoSerializerSnapshot.resolveSchemaCompatibility(...) [step in execution path]
    return resolveSchemaCompatibility(reconfiguredDefaultKryoSerializers, reconfiguredDefaultKryoSerializerClasses, reconfiguredRegistrations);
}

private TypeSerializerSchemaCompatibility<T> resolveSchemaCompatibility(MergeResult<Class<?>, SerializableSerializer<?>> reconfiguredDefaultKryoSerializers, MergeResult<Class<?>, Class<? extends Serializer<?>>> reconfiguredDefaultKryoSerializerClasses, MergeResult<String, KryoRegistration> reconfiguredRegistrations) {
    if ((reconfiguredDefaultKryoSerializers.isOrderedSubset() && reconfiguredDefaultKryoSerializerClasses.isOrderedSubset()) && reconfiguredRegistrations.isOrderedSubset()) {
        return TypeSerializerSchemaCompatibility.compatibleAsIs();
    }
    // reconfigure a new KryoSerializer
    KryoSerializer<T> reconfiguredSerializer = new KryoSerializer<>(snapshotData.getTypeClass(), reconfiguredDefaultKryoSerializers.getMerged(), reconfiguredDefaultKryoSerializerClasses.getMerged(), reconfiguredRegistrations.getMerged());
    return TypeSerializerSchemaCompatibility.compatibleWithReconfiguredSerializer(reconfiguredSerializer);
}

